        while(dir!=g.maze().exitDirection()){actions.add("TURN_RIGHT");dir=(dir+1)%4;}actions.add("FORWARD");return List.copyOf(actions);
    }
    public static void validateSolvable(GameState g){
        GameState single=new GameState(g.seed(),g.level(),g.level(),g.maze(),g.room(),g.direction(),g.remaining(),g.memory(),g.status(),g.moves(),g.actions(),g.collisions(),g.repeats(),g.explored(),g.exitsFound(),g.lastAction(),g.message());
        for(String a:witness(single))single=act(single,a);
        if(!single.status().equals("WON")||single.remaining().stream().anyMatch(x->x<=0))throw new IllegalStateException("level not solvable within entry allowance");
    }
}
